// scripts/i18n/locale-names.ts
// The app name on the home screen, per language.
export const LOCALE_NAMES = { en: 'Tasks', ar: 'المهام' } as const;

// scripts/i18n/native-locales.ts
// The app name and the permission texts per language, for app.config.ts.
import { LOCALE_NAMES } from './locale-names';

export function nativeLocales(): Record<string, { CFBundleDisplayName: string }> {
  return Object.fromEntries(Object.entries(LOCALE_NAMES).map(([tag, name]) => [tag, { CFBundleDisplayName: name }]));
}

